def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    result = []
    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            if stack:
                result.append(current_group)
                current_group = ""
            stack.append(char)
        elif char == ")":
            stack.pop()
            if not stack:
                result.append(current_group)
                current_group = ""
        else:
            current_group += char

    return result

